const body = $input.first().json.body;

const projectTitle = body.projectTitle || 'Untitled Project';
const projectDescription = body.projectDescription || 'No project description provided.';
const milestoneTitle = body.milestoneTitle || 'Untitled Milestone';
const milestoneDescription = body.milestoneDescription || 'No milestone description provided.';
const proofText = body.proofText || '';
const proofFileName = body.proofFileName || '';
let proofFileContent = '';

// Decode text file if present (skip image data)
if (body.proofFileData && body.proofFileData.startsWith('data:text/')) {
  try {
    const base64Part = body.proofFileData.split(',')[1];
    proofFileContent = Buffer.from(base64Part, 'base64').toString('utf-8').substring(0, 3000);
  } catch(e) {
    proofFileContent = '[could not decode text file]';
  }
} else if (body.proofFileData && body.proofFileData.startsWith('data:image/')) {
  proofFileContent = '[An image file was attached. Consider the file name and submission text as evidence.]';
}

const prompt = `You are an impartial AI auditor for a decentralized freelancing platform called Nexrow. Your ONLY job is to determine whether the freelancer's submitted work satisfies the client's requirements for this specific milestone.

--- PROJECT CONTEXT ---
Project Title: ${projectTitle}
Client's Project Requirements: ${projectDescription}

--- MILESTONE DETAILS ---
Milestone Title: ${milestoneTitle}
Milestone Scope: ${milestoneDescription}

--- FREELANCER'S SUBMISSION ---
Submission Notes: ${proofText || '(No text notes provided)'}
Attached File Name: ${proofFileName || '(No file attached)'}
Attached File Content: ${proofFileContent || '(No readable file content)'}

--- YOUR TASK ---
Carefully analyze the freelancer's submission against the client's requirements and the milestone scope.

Respond ONLY with a valid JSON object in this exact format:
{
  "satisfied": true or false,
  "reason": "A detailed 1-3 sentence explanation of your decision. If satisfied, confirm what was delivered. If not satisfied, clearly state what is missing or incorrect and what the freelancer must do to fix it."
}

Do NOT include any text outside the JSON object.`;

return [{ json: { prompt, projectId: body.projectId, milestoneId: body.milestoneId } }];

const geminiResponse = $input.first().json;
const milestoneId = $('Prepare AI Prompt').first().json.milestoneId;
const projectId = $('Prepare AI Prompt').first().json.projectId;

let result;
try {
  const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  result = JSON.parse(rawText.trim());
} catch(e) {
  // Fallback: if parsing fails, mark as not satisfied
  result = {
    satisfied: false,
    reason: 'AI evaluation failed to produce a valid response. Please review the submission manually.'
  };
}

if (typeof result.satisfied !== 'boolean') {
  result.satisfied = false;
  result.reason = result.reason || 'AI response was ambiguous. Please review manually.';
}

return [{ json: { ...result, milestoneId, projectId } }];
